```matlab
% Intelligent Driver Model (IDM)
% Parameters:
%   - v0: initial speed
%   - v_max: maximum speed
%   - a_max: maximum acceleration
%   - b: maximum deceleration
%   - c: initial distance
%   - d: lane change probability

function dxdt = idm(v, x, a, d, beta)
    % Intelligent Driver Model equations
    % dx/dt = v
    % dv/dt = a
    % da/dt = -a
    % dv/dt = a_max * (v / (v + v_max) - 1)
    % dv/dt = d * v * (v / (v + v_max) - 1)
    % dv/dt = -b * v
    % dv/dt = -d * v

    % Update speed and acceleration
    dxdt(1) = v;
    dxdt(2) = a;

    % Update acceleration
    dxdt(3) = -a;
    dxdt(4) = a_max * (v / (v + v_max) - 1);

    % Update distance and lane change
    if rand < beta
        dxdt(5) = d * v * (v / (v + v_max) - 1);
    else
        dxdt(5) = -b * v;
    end
end

% Parameters
v0 = 10; % initial speed
v_max = 50; % maximum speed
a_max = 5; % maximum acceleration
b = 5; % maximum deceleration
c = 100; % initial distance
d = 0.1; % lane change probability
beta = 0.1; % lane change probability

% Number of cars
n_cars = 10;

% Initialize arrays to store simulation data
v_cars = zeros(n_cars, 1);
x_cars = zeros(n_cars, 1);
a_cars = zeros(n_cars, 1);
d_cars = zeros(n_cars, 1);

% Initialize arrays to store simulation data
v_cars(1) = v0;
x_cars(1) = c;
a_cars(1) = 0;
d_cars(1) = 0;

% Time array
t = 0:0.1:10;

% Simulation loop
for i = 2:n_cars
    % IDM solver
    [t_vec, v_cars_vec, a_cars_vec, d_cars_vec] = ode45(@(t, v, x, a, d) idm(v, x, a, d, beta), t, [v_cars(i-1), x_cars(i-1), a_cars(i-1), d_cars(i-1)], [v0, v_max, a_max, b]);

    % Update simulation data
    v_cars(i) = v_cars_vec(end);
    x_cars(i) = x_cars_vec(end);
    a_cars(i) = a_cars_vec(end);
    d_cars(i) = d_cars_vec(end);
end

% Plot simulation results
figure;
for i = 1:n_cars
    plot(t, v_cars(i), 'b.-');
    hold on;
end
xlabel('Time (s)');
ylabel('Speed (m/s)');
title('Speed of cars over time');

figure;
for i = 1:n_cars
    plot(t, x_cars(i), 'b.-');
    hold on;
end
xlabel('Time (s)');
ylabel('Distance (m)');
title('Distance of cars over time');

figure;
for i = 1:n_cars
    plot(t, a_cars(i), 'b.-');
    hold on;
end
xlabel('Time (s)');
ylabel('Acceleration (m/s^2)');
title('Acceleration of cars over time');

figure;
for i = 1:n_cars
    plot(t, d_cars(i), 'b.-');
    hold on;
end
xlabel('Time (s)');
ylabel('Lane change');
title('Lane change of cars over time');
